  async function cwDec(t, d, dec, st) { const j = (d.j || []).find(x => String(x.id) === t.dataset.i), tech = meTech(d) || {}; try { const r = await patch('WS_Jobs_tbl', j.id, { Decision: dec, Decision_By: str(tech.techname) || me(), Decision_At: nowS(), Job_Status: st, Decision_Note: 'Mobile · estimate ' + fmtN(j.esttotal) + ' vs book value ' + fmtN(j.bookvalue) }); saved(r, str(j.jobno) + ' → ' + dec); reload('x_cwappr'); } catch (e) { fail(dec, e); } }
